import ast
import json
from collections import Counter
def task_func(file_pointer):
    """
    Reads from a given file pointer to a JSON file, evaluates strings that represent dictionaries to actual dictionaries, 
    and counts the frequency of each key across all dictionary entries in the JSON data.

    Parameters:
    file_pointer (file object): A file pointer to a JSON file containing a list of dictionaries or strings that can be evaluated as dictionaries.

    Returns:
    collections.Counter: A Counter object representing the frequency of each key found in the dictionaries.
    """
    try:
        data = json.load(file_pointer)
    except json.JSONDecodeError:
        return Counter()

    if not isinstance(data, list):
        return Counter()

    all_keys = []

    for item in data:
        if isinstance(item, dict):
            all_keys.extend(item.keys())
        elif isinstance(item, str):
            try:
                evaluated_dict = ast.literal_eval(item)
                if isinstance(evaluated_dict, dict):
                    all_keys.extend(evaluated_dict.keys())
            except (ValueError, SyntaxError):
                continue

    return Counter(all_keys)

